import CursorTerminal from "./cursor-terminal"

export default function Page() {
  return <CursorTerminal />
}

"use client"

import { ChevronDown, ChevronUp, MoreHorizontal, Plus, Terminal, X } from "lucide-react"
import { cn } from "@/lib/utils"

import { useTerminalAnimation } from "./hooks/use-terminal-animation"
import Spinner from "./components/spinner"
import PromptShell from "./components/prompt-shell"
import PanelIconButton from "./components/panel-icon-button"
import { ICON_SM, ICON_XS, PANEL_TABS, type LineColor } from "./lib/config"

import "./styles/cursor-terminal.css"

function colorCls(c?: LineColor) {
  if (c === "green") return "text-[#16c60c]"
  if (c === "cyan") return "text-[#61d6d6]"
  if (c === "dim") return "text-[#767676]"
  return "text-[#cccccc]"
}

function renderFirstStepCommand(text: string) {
  const npxToken = "npx"
  const commandPrefix = "npx shadcn@latest add "

  if (!text.startsWith(npxToken)) {
    return <span className="min-w-0">{text}</span>
  }

  const npxEnd = npxToken.length
  const argStart = commandPrefix.length

  return (
    <span className="min-w-0">
      <span className="text-[#dcdcaa]">{npxToken}</span>
      {text.slice(npxEnd, Math.min(text.length, argStart))}
      {text.length > argStart && (
        <span className="text-[#4fc1ff]">{text.slice(argStart)}</span>
      )}
    </span>
  )
}

export default function CursorTerminal() {
  const { lines, prompt, scrollRef } = useTerminalAnimation()

  return (
    <div className="crt-terminal w-full overflow-hidden rounded-md border border-white/8 bg-[#1e1e1e] shadow-lg shadow-black/40">
      <div className="flex h-9 min-h-9 select-none items-stretch border-b border-white/6 bg-[#252526]">
        <div className="flex min-w-0 flex-1 items-stretch overflow-x-auto [&::-webkit-scrollbar]:hidden">
          {PANEL_TABS.map((name) => {
            const active = name === "Terminal"
            return (
              <button
                key={name}
                type="button"
                aria-hidden
                tabIndex={-1}
                className={cn(
                  "shrink-0 px-3 text-[11px] transition-colors",
                  active
                    ? "border-t border-t-[#007fd4] bg-[#1e1e1e] text-[#e8e8e8]"
                    : "border-t border-t-transparent text-[#858585] hover:text-[#c0c0c0]",
                )}
              >
                {name}
              </button>
            )
          })}
        </div>

        <div className="flex shrink-0 items-center gap-px pr-1 pl-2">
          <button
            type="button"
            aria-hidden
            tabIndex={-1}
            className="flex h-7 items-center gap-1 rounded px-1.5 text-[12px] text-[#cccccc] transition-colors hover:bg-white/6"
          >
            <Terminal className={cn(ICON_SM, "text-[#3b8eea]")} aria-hidden />
            <span className="max-w-22 truncate sm:max-w-none">powershell</span>
            <ChevronDown className={cn(ICON_XS, "text-[#858585]")} aria-hidden />
          </button>
          <PanelIconButton label="New terminal" className="w-auto min-w-7 gap-0.5 px-1">
            <Plus className={ICON_SM} aria-hidden />
            <ChevronDown className={cn(ICON_XS, "text-[#a0a0a0]")} aria-hidden />
          </PanelIconButton>
          <PanelIconButton label="More">
            <MoreHorizontal className={ICON_SM} aria-hidden />
          </PanelIconButton>
          <PanelIconButton label="Maximize panel">
            <ChevronUp className={ICON_SM} aria-hidden />
          </PanelIconButton>
          <PanelIconButton label="Close panel" hoverDanger>
            <X className={ICON_SM} aria-hidden />
          </PanelIconButton>
        </div>
      </div>

      <div
        ref={scrollRef}
        className="crt-body h-88 overflow-y-auto bg-[#1e1e1e] px-4 py-2.5 text-left font-mono text-[13px] leading-relaxed text-[#cccccc]"
        style={{ scrollbarWidth: "none" }}
      >
        {lines.map((line) => (
          line.promptLine ? (
            <div key={line.id}>
              <div className="flex min-w-0 flex-wrap items-center gap-x-1 gap-y-0">
                <PromptShell dot={line.dot ?? "grey"} showPath />
                {renderFirstStepCommand(line.text)}
              </div>
            </div>
          ) : (
            <div key={line.id} className={cn("crt-line-in", colorCls(line.color))}>
              {line.spinning ? (
                <span><Spinner /> {line.text}</span>
              ) : (
                line.text || "\u00A0"
              )}
            </div>
          )
        ))}

        {prompt.showPrompt && (
          <div className={cn("flex min-w-0 flex-wrap items-center gap-x-1 gap-y-0", prompt.animateIn && "crt-line-in")}>
            <PromptShell dot={prompt.dot} showPath={prompt.showPath} />
            {prompt.typed && renderFirstStepCommand(prompt.typed)}
            {prompt.cursor && <span className="crt-cursor" />}
          </div>
        )}
      </div>

      <div className="border-t border-white/6 bg-[#1e1e1e] py-2 text-center text-[11px] text-[#6e6e6e]">
        Ctrl+K to generate command
      </div>
    </div>
  )
}

import type { ReactNode } from "react"
import { cn } from "@/lib/utils"

export default function PanelIconButton({
  children,
  label,
  hoverDanger,
  className,
}: {
  children: ReactNode
  label: string
  hoverDanger?: boolean
  className?: string
}) {
  return (
    <button
      type="button"
      aria-label={label}
      title={label}
      tabIndex={-1}
      className={cn(
        "flex size-7 items-center justify-center rounded text-[#c8c8c8] transition-colors",
        hoverDanger ? "hover:bg-[#c42b1c]/90 hover:text-white" : "hover:bg-white/8",
        className,
      )}
    >
      {children}
    </button>
  )
}

import { PROMPT } from "../lib/config"
import type { PromptState } from "../lib/config"

type Props = Pick<PromptState, "dot" | "showPath">

export default function PromptShell({ dot, showPath }: Props) {
  return (
    <div className="flex items-center gap-2">
      <span
        className={`inline-block size-[7px] shrink-0 rounded-full ring-1 ring-white/15 ${dot === "blue" ? "bg-[#3b8eea]" : "bg-[#767676]"}`}
        aria-hidden
      />
      {showPath && <span className="tabular-nums">{PROMPT}</span>}
    </div>
  )
}

"use client"

import { useEffect, useState } from "react"

const FRAMES = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"]

export default function Spinner() {
  const [frame, setFrame] = useState(0)
  useEffect(() => {
    const t = setInterval(() => setFrame((f) => (f + 1) % FRAMES.length), 80)
    return () => clearInterval(t)
  }, [])
  return <span>{FRAMES[frame]}</span>
}

// Phase flow: idle → typing → output → done → idle (loops)
import { useEffect, useMemo, useRef, useState } from "react"

import {
  COMMAND, INIT_LINES, OUTPUT_SEQUENCE, PROMPT, TYPE_SPEED,
  type Line, type Phase, type PromptState,
} from "../lib/config"

export function useTerminalAnimation() {
  const [lines, setLines] = useState<Line[]>(INIT_LINES)
  const [typed, setTyped] = useState("")
  const [phase, setPhase] = useState<Phase>("idle")
  const [outIdx, setOutIdx] = useState(0)
  const [firstStepBlue, setFirstStepBlue] = useState(false)
  const idRef = useRef(10)
  const spinTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const scrollRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight
    }
  }, [lines, typed])

  useEffect(() => {
    if (phase !== "idle") return
    const t = setTimeout(() => setPhase("typing"), 1600)
    return () => clearTimeout(t)
  }, [phase])

  useEffect(() => {
    if (phase !== "typing") return
    if (typed.length < COMMAND.length) {
      const t = setTimeout(() => setTyped(COMMAND.slice(0, typed.length + 1)), TYPE_SPEED)
      return () => clearTimeout(t)
    }
    const t = setTimeout(() => {
      setLines((prev) => [...prev, { id: idRef.current++, text: COMMAND, promptLine: true, dot: "grey" }])
      setTyped("")
      setOutIdx(0)
      setPhase("output")
    }, 360)
    return () => clearTimeout(t)
  }, [phase, typed])

  useEffect(() => {
    if (phase !== "output") return
    if (outIdx >= OUTPUT_SEQUENCE.length) {
      const t = setTimeout(() => setPhase("done"), 500)
      return () => clearTimeout(t)
    }
    const item = OUTPUT_SEQUENCE[outIdx]
    if (item.type === "spinner") {
      const t = setTimeout(() => {
        const spinId = idRef.current++
        setLines((prev) => [...prev, { id: spinId, text: item.text, spinning: true }])
        spinTimerRef.current = setTimeout(() => {
          setLines((prev) =>
            prev.map((l) =>
              l.id === spinId
                ? { ...l, spinning: false, text: `✓ ${item.doneText ?? item.text}`, color: "green" as const }
                : l,
            ),
          )
          setOutIdx((i) => i + 1)
        }, item.duration)
      }, item.delay)
      return () => {
        clearTimeout(t)
        if (spinTimerRef.current) clearTimeout(spinTimerRef.current)
      }
    }
    const t = setTimeout(() => {
      setLines((prev) => [...prev, { id: idRef.current++, text: item.text, color: item.color }])
      setOutIdx((i) => i + 1)
    }, item.delay)
    return () => clearTimeout(t)
  }, [phase, outIdx])

  useEffect(() => {
    if (phase !== "done") return
    setLines((prev) => prev.map((line) => (line.promptLine ? { ...line, dot: "grey" } : line)))
    setFirstStepBlue(false)
    const blueTimer = setTimeout(() => {
      setFirstStepBlue(true)
      setLines((prev) => prev.map((line) => (line.promptLine ? { ...line, dot: "blue" } : line)))
    }, 700)
    const resetTimer = setTimeout(() => {
      idRef.current = 10
      setTyped("")
      setOutIdx(0)
      setFirstStepBlue(false)
      setLines(INIT_LINES)
      setPhase("idle")
    }, 5500)
    return () => {
      clearTimeout(blueTimer)
      clearTimeout(resetTimer)
    }
  }, [phase])

  const prompt = useMemo<PromptState>(() => {
    switch (phase) {
      case "idle":
        return { dot: "grey", showPrompt: true, showPath: true, typed: "", cursor: true, animateIn: false }
      case "typing":
        return { dot: "grey", showPrompt: true, showPath: true, typed, cursor: true, animateIn: false }
      case "output":
        return { dot: "grey", showPrompt: false, showPath: false, typed: "", cursor: false, animateIn: false }
      case "done":
        return {
          dot: "grey",
          showPrompt: true,
          showPath: true,
          typed: "",
          cursor: false,
          animateIn: true,
        }
    }
  }, [firstStepBlue, phase, typed])

  return { lines, prompt, scrollRef }
}

/* cursor-terminal — scoped so consumers need not import app globals */

.crt-terminal .crt-cursor {
  display: inline-block;
  width: 8px;
  height: 1em;
  margin-left: 1px;
  vertical-align: text-bottom;
  background-color: #cccccc;
  animation: crt-terminal-blink 1.15s step-start infinite;
}

@keyframes crt-terminal-blink {
  0%,
  49.9% {
    opacity: 1;
  }
  50%,
  100% {
    opacity: 0;
  }
}

.crt-terminal .crt-line-in {
  animation: crt-terminal-line-fade 0.12s ease-out both;
}

@keyframes crt-terminal-line-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.crt-terminal .crt-body::-webkit-scrollbar {
  display: none;
}
